function splitLines(text) {
  const match = text.match(/\r\n|\n|\r/);
  const newline = match ? match[0] : '\n';
  const hasFinalNewline = /(?:\r\n|\n|\r)$/.test(text);
  const lines = text.split(/\r\n|\n|\r/);

  if (hasFinalNewline) {
    lines.pop();
  }

  return { lines, newline, hasFinalNewline };
}

function process(data) {
  const text = data && data.selection;
  if (typeof text !== 'string') {
    throw new TypeError('selection must be a string');
  }

  const { lines, newline, hasFinalNewline } = splitLines(text);
  const output = lines.reverse().join(newline);
  return output + (hasFinalNewline ? newline : '');
}
